def mm_to_rgb(slice2d):
    lo, hi = -1350.0, 150.0
    x = np.clip((slice2d.astype(np.float32) - lo)/(hi - lo), 0, 1)
    return np.asarray(Image.fromarray((x*255).astype(np.uint8)).convert('RGB').resize((IMG, IMG)), dtype=np.uint8)
