    Z = vol.shape[2]; a, b = int(0.25*Z), max(int(0.75*Z), int(0.25*Z)+1)
    for z in np.linspace(a, b-1, min(SLICES_PER_VOLUME, b-a)).astype(int):
        mm_slices.append(mm_to_rgb(vol[:, :, z])); mm_slice_vol.append(vi)
